import 'package:flutter_alarmkit/flutter_alarmkit.dart';

final kit = FlutterAlarmkit();
await kit.requestAuthorization();
await kit.scheduleOneShotAlarm(
  timestamp: DateTime.now().add(const Duration(hours: 1)).millisecondsSinceEpoch.toDouble(),
  label: 'Wake up',
  soundPath: 'assets/sounds/alarm.caf',
);
